  const ids=new Set(CATALOG.map(g=>g.id));
  const CHECKPOINT_KEY='hh.all-game.checkpoints.v1',checkpointKey=owner=>CHECKPOINT_KEY+':'+encodeURIComponent(owner),recordKey=(id,difficulty)=>id+'|'+difficulty+'|1';
  function validSnapshot(state,id){
    if(!state||typeof state!=='object'||state.id!==id||state.status!=='playing')return false;
    const queue=[[state,0]];let count=0;while(queue.length){const [value,depth]=queue.pop();if(++count>18000||depth>22)return false;if(typeof value==='number'&&!Number.isFinite(value)||typeof value==='string'&&value.length>4000)return false;if(value&&typeof value==='object'){const values=Object.values(value);if(values.length>2500)return false;for(const child of values)queue.push([child,depth+1]);}}return true;
  }
  function checkpointItems(storage,owner){try{const raw=storage?.getItem(checkpointKey(owner));if(!raw||raw.length>1500000)return[];const data=JSON.parse(raw);if(data?.version!==1||!Array.isArray(data.items))return[];return data.items.slice(-8).filter(item=>item&&ids.has(item.id)&&['easy','normal','hard'].includes(item.difficulty)&&item.rules===1&&validSnapshot(item.state,item.id));}catch{return[];}}
  function readCheckpoint(storage,owner,id,difficulty){const found=checkpointItems(storage,owner).find(item=>item.id===id&&item.difficulty===difficulty);return found?JSON.parse(JSON.stringify(found.state)):null;}
  function saveCheckpoint(storage,owner,id,difficulty,state){try{if(!storage?.setItem)throw Error('unavailable');let items=checkpointItems(storage,owner).filter(item=>item.id!==id||item.difficulty!==difficulty);if(state?.status==='playing'){if(!validSnapshot(state,id))throw Error('invalid');const snapshot=JSON.stringify(state);if(snapshot.length>160000)throw Error('large');items.push({id,difficulty,rules:1,savedAt:Date.now(),state:JSON.parse(snapshot)});}storage.setItem(checkpointKey(owner),JSON.stringify({version:1,items:items.slice(-8)}));return{ok:true};}catch{return{ok:false,error:'Chưa lưu được điểm tiếp tục. Phiên vẫn giữ tạm trong lần mở này.'};}}
  function account(options={}){return String(options.currentUser?.id||options.currentUser?._id||options.currentUser?.email||'guest').slice(0,300);}
  const keyFor=owner=>KEY+':'+encodeURIComponent(owner);
  function normalizeData(input){
    const raw=input&&typeof input==='object'?input:{},bests=Object.create(null);
    for(const id of ids){const item=raw.bests?.[id];if(!item||typeof item!=='object')continue;bests[id]={score:Math.max(0,Math.min(1e12,Number(item.score)||0)),plays:Math.max(0,Math.min(1e9,Math.floor(Number(item.plays)||0))),wins:Math.max(0,Math.min(1e9,Math.floor(Number(item.wins)||0)))};}
    const records=Object.create(null);for(const id of ids)for(const difficulty of ['easy','normal','hard']){const key=recordKey(id,difficulty),item=raw.records?.[key];if(item&&typeof item==='object')records[key]={score:Math.max(0,Math.min(1e12,Number(item.score)||0)),plays:Math.max(0,Math.min(1e9,Math.floor(Number(item.plays)||0))),wins:Math.max(0,Math.min(1e9,Math.floor(Number(item.wins)||0)))};}
    return{version:VERSION,favorites:[...new Set((Array.isArray(raw.favorites)?raw.favorites:[]).filter(id=>ids.has(id)))],recents:[...new Set((Array.isArray(raw.recents)?raw.recents:[]).filter(id=>ids.has(id)))].slice(0,9),bests,records,difficulty:['easy','normal','hard'].includes(raw.difficulty)?raw.difficulty:'normal',motion:raw.motion!==false};
  }
  function read(storage,owner){try{const raw=storage?.getItem(keyFor(owner));if(raw&&raw.length>50000)return normalizeData();const data=raw?JSON.parse(raw):null;return normalizeData(data?.version===VERSION?data:null);}catch{return normalizeData();}}
  function save(storage,owner,data){try{if(!storage?.setItem)throw Error('unavailable');storage.setItem(keyFor(owner),JSON.stringify(normalizeData(data)));return{ok:true};}catch{return{ok:false,error:'Chưa lưu được trên thiết bị. Dữ liệu hiện chỉ giữ trong lần mở này.'};}}
  function filter(query='',category='all',favoritesOnly=false,favorites=[]){
    const terms=norm(query).trim().split(/\s+/).filter(Boolean),words=g=>norm(g.title+' '+g.description+' '+g.category).split(/[^a-z0-9]+/);
    const rows=CATALOG.filter(g=>(category==='all'||g.category===category)&&(!favoritesOnly||favorites.includes(g.id))&&terms.every(term=>words(g).some(word=>word.startsWith(term))));
    const exact=rows.filter(g=>terms.every(term=>words(g).includes(term)));return exact.length?exact:rows;
  }
